@Test
public void testLocaleIndependence() throws Exception {
    final StringEncoder encoder = this.getStringEncoder();
    final String[] data = { "I", "i" };
    final Locale orig = Locale.getDefault();
    final Locale[] locales = { Locale.ENGLISH, new Locale("tr"), Locale.getDefault() };
    try {
        for (final String element : data) {
            String ref = null;
            for (int j = 0; j < locales.length; j++) {
                Locale.setDefault(locales[j]);
                if (j <= 0) {
                    ref = encoder.encode(element);
                } else {
                    String cur = null;
                    try {
                        cur = encoder.encode(element);
                    } catch (final Exception e) {
                        fail(Locale.getDefault().toString() + ": " + e.getMessage());
                    }
                    assertEquals(ref, cur, Locale.getDefault().toString() + ": ");
                }
            }
        }
    } finally {
        Locale.setDefault(orig);
    }
}

/**
 * Tests skipping past the end of a stream.
 *
 * @throws IOException for some failure scenarios.
 */
@Test
public void testAvailable() throws IOException {
    final InputStream ins = new ByteArrayInputStream(StringUtils.getBytesIso8859_1(ENCODED_B16));
    try (final Base16InputStream b16Stream = new Base16InputStream(ins)) {
        assertEquals(1, b16Stream.available());
        assertEquals(6, b16Stream.skip(10));
        // End of stream reached
        assertEquals(0, b16Stream.available());
        assertEquals(-1, b16Stream.read());
        assertEquals(-1, b16Stream.read());
        assertEquals(0, b16Stream.available());
    }
}

