@Test
public void test() {
    final PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, true);
    final String input = "Angelo";
    final long startMillis = System.currentTimeMillis();
    for (int i = 0; i < LOOP; i++) {
        engine.encode(input);
    }
    final long totalMillis = System.currentTimeMillis() - startMillis;
    System.out.println(String.format("Time for encoding %,d times the input '%s': %,d millis.", LOOP, input, totalMillis));
}

@Test
public void testCompatibilityWithOriginalVersion() {
    // see CODEC-187
    // comparison: http://stevemorse.org/census/soundex.html
    final Map<String, String> args = new TreeMap<>();
    args.put("nameType", "GENERIC");
    args.put("ruleType", "APPROX");
    assertEquals("Ybram|Ybrom|abram|abran|abrom|abron|avram|avrom|obram|obran|obrom|obron|ovram|ovrom", encode(args, true, "abram"));
    assertEquals("bndzn|bntsn|bnzn|vndzn|vntsn", encode(args, true, "Bendzin"));
